const s = $input.first().json;
const errs = [];
const clean = (v) => String(v === null || v === undefined ? '' : v).trim();
const list = (v) => clean(v).split(',').map((x) => x.trim()).filter(Boolean);

let domain = clean(s.freshdesk_domain)
  .replace(/^https?:\/\//, '')
  .replace(/\/+$/, '')
  .replace(/\.freshdesk\.com$/i, '');
if (!domain || domain.toUpperCase().indexOf('YOUR-DOMAIN') !== -1) {
  errs.push('Set freshdesk_domain in the SETTINGS node to your Freshdesk subdomain, the part before .freshdesk.com');
}

const agentId = clean(s.customgpt_agent_id);
if (!agentId || agentId.toUpperCase().indexOf('YOUR-AGENT-ID') !== -1) {
  errs.push('Set customgpt_agent_id in the SETTINGS node to your CustomGPT agent number, the digits in the agent URL');
}

const ticketId = clean(s.ticket_id);
if (!ticketId || /[^0-9]/.test(ticketId)) {
  errs.push('No ticket number. If you are testing, put a real ticket number in the Test Ticket ID node. If this came from Freshdesk, check the automation rule is sending the Ticket ID placeholder');
}

const allowedTags = list(s.allowed_tags);
if (allowedTags.length === 0) {
  errs.push('Fill in allowed_tags in the SETTINGS node - the tags the agent may use, separated by commas');
}

const allowedTypes = list(s.allowed_types);
if (allowedTypes.length === 0) {
  errs.push('Fill in allowed_types in the SETTINGS node - your Freshdesk ticket Types, spelled exactly as Freshdesk spells them');
}

if (errs.length > 0) {
  const numbered = errs.map((e, i) => '(' + (i + 1) + ') ' + e).join('   ');
  throw new Error('SETUP NEEDED - ' + errs.length + ' thing' + (errs.length === 1 ? '' : 's') + ' to fix before this can run:   ' + numbered);
}

return [{
  json: {
    ticket_id: ticketId,
    freshdesk_domain: domain,
    customgpt_agent_id: agentId,
    allowed_tags: allowedTags,
    allowed_types: allowedTypes,
    skip_senders: list(s.skip_senders).map((x) => x.toLowerCase())
  }
}];

const t = $input.first().json;
const NL = String.fromCharCode(10);
const SOURCES = { 1: 'Email', 2: 'Portal', 3: 'Phone', 7: 'Chat', 9: 'Feedback Widget', 10: 'Outbound Email' };
const requester = t.requester || {};

let prompt = '';
prompt += 'Ticket ID: ' + t.id + NL;
prompt += 'Source: ' + (SOURCES[t.source] || t.source) + NL;
prompt += 'Current Type: ' + (t.type || '(unset)') + NL;
prompt += 'Requester: ' + (requester.name || '') + ' <' + (requester.email || '') + '>' + NL;
prompt += 'Subject: ' + (t.subject || '') + NL;
prompt += 'Description:' + NL;
prompt += String(t.description_text || '').slice(0, 2500);

return [{
  json: {
    prompt: prompt,
    ticket_id: t.id,
    current_type: t.type || null,
    source: t.source,
    existing_tags: Array.isArray(t.tags) ? t.tags : []
  }
}];

const cfg = $('Preflight Check').first().json;
const src = $('Build Prompt').first().json;
const BR = '<br>';
const FENCE = String.fromCharCode(96, 96, 96);

const raw = String((($input.first().json || {}).data || {}).openai_response || '');
const answer = raw.split(FENCE).join('').trim();

function field(name) {
  const open = '<' + name + '>';
  const close = '</' + name + '>';
  const a = answer.indexOf(open);
  if (a === -1) { return null; }
  const b = answer.indexOf(close, a + open.length);
  if (b === -1) { return null; }
  return answer.substring(a + open.length, b).trim();
}

const disposition = String(field('disposition') || '').toLowerCase();
if (disposition !== 'action-required' && disposition !== 'no-action-required') {
  throw new Error('The agent did not return a usable disposition. Check the agent instructions match the output format in the README. It replied: ' + answer.slice(0, 300));
}

const proposed = String(field('tags') || '').split(',').map((s) => s.trim()).filter(Boolean);
const rejected = proposed.filter((x) => cfg.allowed_tags.indexOf(x) === -1);
const topic = proposed.filter((x) => cfg.allowed_tags.indexOf(x) !== -1);

const existing = Array.isArray(src.existing_tags) ? src.existing_tags : [];
const seen = {};
const merged = [];
existing.concat([disposition]).concat(topic).forEach((x) => {
  if (x && !seen[x]) { seen[x] = true; merged.push(x); }
});

const typeMissing = String(field('type_is_missing') || '').toLowerCase() === 'true';
let type = field('type');
if (!type || type.toLowerCase() === 'null') { type = null; }
const setType = Boolean(typeMissing && type && cfg.allowed_types.indexOf(type) !== -1 && type !== src.current_type);

const updatePayload = { tags: merged };
if (setType) { updatePayload.type = type; }

const confidence = field('confidence') || 'unknown';
const reasoning = field('reasoning') || '';

let summary = '';
summary += 'Disposition: ' + disposition + BR;
summary += 'Topic tags: ' + (topic.length ? topic.join(', ') : '(none)') + BR;
summary += 'Tags applied: ' + merged.join(', ') + BR;
summary += 'Type: ' + (setType ? 'wanted to set ' + type : 'left unchanged (' + (src.current_type || 'unset') + ')') + BR;
summary += 'Confidence: ' + confidence + BR;
summary += 'Reasoning: ' + reasoning + BR;
if (rejected.length) { summary += '<b>Rejected tags not on your list:</b> ' + rejected.join(', ') + BR; }


return [{
  json: {
    ticket_id: src.ticket_id,
    freshdesk_domain: cfg.freshdesk_domain,
    disposition: disposition,
    topic_tags: topic,
    rejected_tags: rejected,
    set_type: setType,
    type: type,
    confidence: confidence,
    reasoning: reasoning,
    update_payload: updatePayload,
    tags_only_payload: { tags: merged },
    verdict_summary: summary
  }
}];

const BR = '<br>';

function safe(fn, fallback) {
  try { const v = fn(); return (v === undefined || v === null) ? fallback : v; }
  catch (e) { return fallback; }
}

let note = '';
let failedFields = [];
let freshdeskMessage = '';
let unrecognised = false;
let diagnoseError = '';

try {
  const input = safe(() => $input.first().json, {});
  const err = safe(() => input.error, null) || input;

  let raw = '';
  try { raw = JSON.stringify(err); } catch (e) { raw = String(err); }
  if (!raw || raw === '{}' || raw === 'null') { raw = String(safe(() => input.message, '')); }

  freshdeskMessage = String(safe(() => err.message, '') || safe(() => err.description, '')).trim();

  const found = raw.match(/"field"\s*:\s*"([^"]+)"/g) || [];
  found.forEach((s) => {
    const m = s.match(/"field"\s*:\s*"([^"]+)"/);
    if (m && failedFields.indexOf(m[1]) === -1) { failedFields.push(m[1]); }
  });

  const summary = String(safe(() => $('Check The Answer').first().json.verdict_summary, ''));

  note += '<b>Ticket Triage - tags applied, Type not set</b>' + BR + BR;

  if (summary) {
    note += summary + BR;
  } else {
    unrecognised = true;
    note += 'The classification result could not be read back into this note.' + BR + BR;
  }

  note += '<b>Why the full update failed</b>' + BR;

  if (failedFields.length > 0) {
    note += 'Freshdesk rejected the update because of <b>' + failedFields.join(', ') + '</b>.' + BR + BR;
    note += 'Freshdesk revalidates a ticket&rsquo;s required fields whenever the ticket is updated. If one of them is empty the update is rejected as a whole, even though the request never mentioned that field. This most often happens on a ticket that is already closed, where fields marked required on closure are checked again. Tickets that have just arrived are not usually affected.' + BR + BR;
    note += '<b>What to do</b>' + BR;
    note += 'Give that field a value on this ticket, or set a default for it in Freshdesk under Admin &rarr; Ticket Fields so it is never empty. The tags above were applied on their own, so only the Type is missing.' + BR + BR;
  } else if (freshdeskMessage) {
    note += 'Freshdesk returned: ' + freshdeskMessage + BR + BR;
    note += 'The tags above were applied on their own. The Type may need setting by hand.' + BR + BR;
  } else {
    unrecognised = true;
    note += 'The update failed, but the response did not say why in a form this workflow recognises. The tags above were applied on their own.' + BR + BR;
    note += '<b>Raw response</b>' + BR;
    note += String(raw).slice(0, 600) + BR + BR;
  }

  if (unrecognised) {
    note += 'If this keeps happening, send this note to whoever maintains the workflow &mdash; the raw response above is what they need.' + BR + BR;
  }

  note += '<i>To stop these notes, open this workflow in n8n and disable the "Explain What Failed" node. Tags will still be applied.</i>';
} catch (e) {
  diagnoseError = String(safe(() => e.message, e));
  unrecognised = true;
  note = '<b>Ticket Triage - tags applied, Type not set</b>' + BR + BR +
    'The update failed and this note could not be built properly: ' + diagnoseError + BR + BR +
    'The tags were still applied. Send this note to whoever maintains the workflow.' + BR + BR +
    '<i>To stop these notes, open this workflow in n8n and disable the "Explain What Failed" node.</i>';
}

return [{ json: { note: note, failed_fields: failedFields, freshdesk_message: freshdeskMessage, unrecognised: unrecognised, diagnose_error: diagnoseError } }];
